438	/* Performs old-style TrueType kerning. */
439	void
440	_hb_ot_shape_fallback_kern (const hb_ot_shape_plan_t *plan,
441				    hb_font_t *font,
442				    hb_buffer_t  *buffer)
443	{
444	  if (!plan->has_kern) return;
445	
446	  OT::hb_ot_apply_context_t c (1, font, buffer);
447	  hb_mask_t kern_mask = plan->kern_mask;
448	  c.set_lookup_mask (kern_mask);
449	  c.set_lookup_props (OT::LookupFlag::IgnoreMarks);
450	  OT::hb_ot_apply_context_t::skipping_iterator_t &skippy_iter = c.iter_input;
451	  skippy_iter.init (&c);
452	
453	  unsigned int count = buffer->len;
454	  hb_glyph_info_t *info = buffer->info;
455	  hb_glyph_position_t *pos = buffer->pos;
456	  for (unsigned int idx = 0; idx < count;)
457	  {
458	    if (!(buffer->cur().mask & kern_mask))
459	    {
460	      idx++;
461	      continue;
462	    }
463	
464	    skippy_iter.reset (idx, 1);
465	    if (!skippy_iter.next ())
466	    {
467	      idx++;
468	      continue;
469	    }
470	
471	    hb_position_t x_kern, y_kern;
472	    font->get_glyph_kerning_for_direction (info[idx].codepoint,
473						   info[skippy_iter.idx].codepoint,
474						   buffer->props.direction,
475						   &x_kern, &y_kern);
476	
477	    if (x_kern)
478	    {
479	      hb_position_t kern1 = x_kern >> 1;
480	      hb_position_t kern2 = x_kern - kern1;
481	      pos[idx].x_advance += kern1;
482	      pos[skippy_iter.idx].x_advance += kern2;
483	      pos[skippy_iter.idx].x_offset += kern2;
484	      buffer->unsafe_to_break (idx, skippy_iter.idx + 1);
485	    }
486	
487	    if (y_kern)
488	    {
489	      hb_position_t kern1 = y_kern >> 1;
490	      hb_position_t kern2 = y_kern - kern1;
491	      pos[idx].y_advance += kern1;
492	      pos[skippy_iter.idx].y_advance += kern2;
493	      pos[skippy_iter.idx].y_offset += kern2;
494	      buffer->unsafe_to_break (idx, skippy_iter.idx + 1);
495	    }
496	
497	    idx = skippy_iter.idx;
498	  }
499	}
