502	/* Adjusts width of various spaces. */
503	void
504	_hb_ot_shape_fallback_spaces (const hb_ot_shape_plan_t *plan,
505				      hb_font_t *font,
506				      hb_buffer_t  *buffer)
507	{
508	  if (!HB_DIRECTION_IS_HORIZONTAL (buffer->props.direction))
509	    return;
510	
511	  hb_glyph_info_t *info = buffer->info;
512	  hb_glyph_position_t *pos = buffer->pos;
513	  unsigned int count = buffer->len;
514	  for (unsigned int i = 0; i < count; i++)
515	    if (_hb_glyph_info_is_unicode_space (&info[i]) && !_hb_glyph_info_ligated (&info[i]))
516	    {
517	      hb_unicode_funcs_t::space_t space_type = _hb_glyph_info_get_unicode_space_fallback_type (&info[i]);
518	      hb_codepoint_t glyph;
519	      typedef hb_unicode_funcs_t t;
520	      switch (space_type)
521	      {
522		case t::NOT_SPACE: /* Shouldn't happen. */
523		case t::SPACE:
524		  break;
525	
526		case t::SPACE_EM:
527		case t::SPACE_EM_2:
528		case t::SPACE_EM_3:
529		case t::SPACE_EM_4:
530		case t::SPACE_EM_5:
531		case t::SPACE_EM_6:
532		case t::SPACE_EM_16:
533		  pos[i].x_advance = (font->x_scale + ((int) space_type)/2) / (int) space_type;
534		  break;
535	
536		case t::SPACE_4_EM_18:
537		  pos[i].x_advance = (int64_t) font->x_scale * 4 / 18;
538		  break;
539	
540		case t::SPACE_FIGURE:
541		  for (char u = '0'; u <= '9'; u++)
542		    if (font->get_nominal_glyph (u, &glyph))
543		    {
544		      pos[i].x_advance = font->get_glyph_h_advance (glyph);
545		      break;
546		    }
547		  break;
548	
549		case t::SPACE_PUNCTUATION:
550		  if (font->get_nominal_glyph ('.', &glyph))
551		    pos[i].x_advance = font->get_glyph_h_advance (glyph);
552		  else if (font->get_nominal_glyph (',', &glyph))
553		    pos[i].x_advance = font->get_glyph_h_advance (glyph);
554		  break;
555	
556		case t::SPACE_NARROW:
557		  /* Half-space?
558		   * Unicode doc https://unicode.org/charts/PDF/U2000.pdf says ~1/4 or 1/5 of EM.
559		   * However, in my testing, many fonts have their regular space being about that
560		   * size.  To me, a percentage of the space width makes more sense.  Half is as
561		   * good as any. */
562		  pos[i].x_advance /= 2;
563		  break;
564	      }
565	    }
566	}
